
const layer=document.querySelector('.detail-layer'), panel=layer.querySelector('.detail-panel'), roller=document.querySelector('.rolling-capsule'), reel=document.querySelector('.reel-transition');
const asset=id=>`../assets/capsule/${id}.svg`;let busy=false;
function openHost(id,el){if(busy)return;busy=true;const h=PROTO.byId(id),r=el.querySelector('img').getBoundingClientRect();PROTO.state.selected=id;PROTO.fillDetail(panel,h,asset(id));roller.querySelector('img').src=asset(id);roller.style.setProperty('--sx',`${r.left+r.width/2}px`);roller.style.setProperty('--sy',`${r.top+r.height/2}px`);roller.classList.remove('go');void roller.offsetWidth;roller.classList.add('go');setTimeout(()=>{layer.classList.add('open');layer.setAttribute('aria-hidden','false')},380);setTimeout(()=>{roller.classList.remove('go');busy=false},680)}
function closeDetail(silent=false){layer.classList.remove('open');layer.setAttribute('aria-hidden','true');PROTO.state.selected=null}
document.querySelectorAll('.capsule-card').forEach(el=>el.addEventListener('click',()=>openHost(el.dataset.host,el)));layer.querySelector('.close-detail').onclick=()=>closeDetail();layer.querySelector('.detail-backdrop').onclick=()=>closeDetail();PROTO.onEscape(closeDetail);PROTO.bindNav({closeDetail,before(){reel.classList.remove('go');void reel.offsetWidth;reel.classList.add('go')}});PROTO.bindSettings();
